mod common;
use common::{Fixture,envelope};
use kingmaker_io::SqliteLoader;
use serde_json::json;
#[test]fn authored_profession_changes_and_full_rights_are_visible_without_money_or_reseed(){let f=Fixture::new();f.add_record("registry/reference",0,json!("#global"),envelope("registry/reference",json!({"professions":[{"pop_type_id":"craftsmen","transition_requirements":{"kind":"funded_vacancy","source":"author"}}],"author_formula":"keep"})));for(table,id,row)in[("capitalistEntities",json!("capital"),json!({"id":"capital","beneficiaries":[{"pop_id":"pop:1","share":0.6}],"author":"keep"})),("projectInvestments",json!("investment"),json!({"id":"investment","investor_id":"pop:1","amount_minor":"999999999999","author":"keep"})),("productionBeneficiaries",json!(7),json!({"id":7,"pop_id":7,"share":0.6})),("factoryBeneficiaries",json!("7"),json!({"id":"7","pop_id":"7","share":0.25})),("shipments",json!("cargo"),json!({"id":"cargo","owner_id":"pop:1","status":"in_transit","stock_id":7,"remaining_quantity":3.25,"author_formula":"keep"}))]{let name=format!("registry/{table}");f.add_record(&name,0,id,envelope(&name,row));}let before=SqliteLoader::load_from_path(&f.path,"fixture").unwrap();assert_eq!(before.mobility_data.reference.as_ref().unwrap()["author_formula"],json!("keep"));assert_eq!(before.mobility_data.capitalist_entities[0]["beneficiaries"][0]["share"],json!(0.6));assert_eq!(before.mobility_data.project_investments[0]["amount_minor"],json!("999999999999"));assert_eq!(before.mobility_data.production_beneficiaries[0]["pop_id"],json!(7));assert_eq!(before.mobility_data.factory_beneficiaries[0]["pop_id"],json!("7"));assert_eq!(before.mobility_data.shipments[0]["stock_id"],json!(7));f.sql("UPDATE km_entity SET payload=json_set(payload,'$.value.professions[0].transition_requirements.kind','education') WHERE table_name='registry/reference'");let after=SqliteLoader::load_from_path(&f.path,"fixture").unwrap();assert_eq!(after.mobility_data.reference.as_ref().unwrap()["professions"][0]["transition_requirements"]["kind"],json!("education"));assert_eq!(before.pops,after.pops);assert_eq!(before.accounts,after.accounts);assert_eq!(before.stockpiles,after.stockpiles);let roundtrip:kingmaker_core::WorldState=serde_json::from_value(serde_json::to_value(&after).unwrap()).unwrap();assert_eq!(roundtrip.mobility_data,after.mobility_data);}
#[test]fn absent_reference_is_not_permission_and_mutable_rights_survive_roundtrip(){let f=Fixture::new();let mut w=SqliteLoader::load_from_path(&f.path,"fixture").unwrap();assert!(w.mobility_data.reference.is_none());w.mobility_data.shipments.push(json!({"id":"cargo","owner_id":"child","remaining_quantity":1.5,"custom_title":{"pop_id":"child"}}));w.mobility_data.project_investments.push(json!({"id":"new","amount_minor":"20","investor_id":"child"}));let restored:kingmaker_core::WorldState=serde_json::from_value(serde_json::to_value(&w).unwrap()).unwrap();assert_eq!(restored.mobility_data,w.mobility_data);assert_eq!(restored.accounts,w.accounts);}
#[test]fn stock_author_terms_are_native_and_roundtrip_without_identity_shadow(){let f=Fixture::new();f.sql("UPDATE km_entity SET payload=json_set(payload,'$.value.author_formula','keep','$.value.external_id','author-only','$.value.custom_title',json('{\"pop_id\":7,\"policy\":\"keep\"}')) WHERE table_name='stocks'");let w=SqliteLoader::load_from_path(&f.path,"fixture").unwrap();assert_eq!(w.stockpiles[0].extra["author_formula"],json!("keep"));assert_eq!(w.stockpiles[0].extra["custom_title"]["pop_id"],json!(7));let roundtrip:kingmaker_core::WorldState=serde_json::from_value(serde_json::to_value(&w).unwrap()).unwrap();assert_eq!(roundtrip.stockpiles,w.stockpiles);assert_ne!(w.stockpiles[0].external_id.as_str(),Some("author-only"));}
